import type { Arc } from '../types';
import { arc, battle, beat } from './arc-helpers';

/** Paradise after Alabasta: Jaya through Thriller Bark. */
export const paradiseArcs: Arc[] = [
arc({
  id: 'jaya', name: 'Jaya', sagaId: 'sky-island', chapters: [218, 236],
  premise: 'When the compass points at the sky, believing the impossible becomes a practical problem.',
  locationIds: ['jaya', 'mock-town', 'going-merry'], characterIds: ['luffy', 'zoro', 'nami', 'robin'],
  overview: ['A ship falls from the sky and the Log Pose begins pointing upward. With Robin newly aboard, the crew has both a navigator asking how the route can exist and an archaeologist interested in what the falling wreck preserves. Jaya becomes the place where an apparently absurd destination must acquire evidence, preparation, and a departure method.', 'Mock Town celebrates the pirates who dismiss dreams they cannot immediately profit from. Bellamy treats the search for a sky island as grounds for humiliation. Luffy and Zoro decline to fight over the insult, recalling Shanks’s distinction between injured pride and a threat that actually matters. Across the street, an unnamed pirate who will prove to be Blackbeard argues that dreams endure, establishing an uncomfortable point of resemblance between future enemies.'],
  beats: [
    beat('mock-town', 'An insult is not the battle', '218–225', [
      'The morning after Alabasta the Log Pose needle tilts straight up, and before Nami can finish declaring it broken a galleon two centuries old drops out of the clouds and breaks across the Merry’s bow. Robin, one day into her membership, dives with the salvage and surfaces with a map of a place called Skypiea. Masira’s salvage crew arrives to claim the wreck, and the only island the needle also acknowledges is Jaya, a pirate stopover with no reputation for honesty.',
      'Mock Town treats questions as invitations. In a hotel bar, Bellamy the Hyena and his lieutenant Sarquiss hear Luffy ask about a sky island and decide that the new age has no room for men who chase legends. Bellamy springs off the walls and beats Luffy and Zoro through the furniture while the town cheers, and neither of them raises a hand. Nami is furious until she remembers that Shanks once bled for exactly this distinction.',
      'On the street outside, a broad, laughing pirate who earlier argued with Luffy about cherry pie shouts after them that dreams never end. He is right, and he will later prove to be Blackbeard. The crew walks away from Mock Town with a bruised captain, an unspent grudge, and one piece of information: a man named Mont Blanc Cricket lives on the far side of the island, and everyone here despises him.'
    ]),
    beat('crickets-evidence', 'A descendant lives with a disputed story', '226–229', [
      'Cricket’s house is a ship’s hull with a shack bolted to its side, guarded by Masira and Shoujou, the salvaging monkeys who call him boss. He greets Luffy with a punch and the crew with the children’s book that made his family a joke: Noland the Liar, the explorer executed four hundred years ago for reporting a city of gold that no one could find again. Cricket dives every day for the gold that would prove the old man was not a fraud.',
      'Robin reads the actual logbook rather than the picture book and finds a navigator’s precision behind the fairy tale. Cricket explains the only theory that fits the falling ship and the tilted needle: an island of earth carried into the clouds by a Knock Up Stream, the column of seawater that erupts from this ocean a few times a year. To ride it the Merry needs reinforcing, a heading, and a South Bird whose head always points the right way.',
      'The night becomes a working plan. Masira and Shoujou promise to rebuild the Merry by dawn, Cricket marks the stream’s likely position, and the crew goes into the forest with nets to catch a bird that mocks them from the branches. For the first time since the needle moved, the sky island is a problem with steps rather than a joke that other people tell.'
    ]),
    beat('a-real-reason', 'A real reason to throw a punch', '230–232', [
      'While the crew chases the South Bird through the dark, Bellamy comes down the beach with his crew, beats Cricket and the monkeys, and carries off the gold that took ten years to raise from the seabed. The Straw Hats return with the bird to find their hosts bleeding and the house emptied. Cricket, still bound to his father’s shame, tells them the stream will not wait and that gold was never the point.',
      'Luffy runs back to Mock Town anyway, and the run changes what the earlier beating meant. Bellamy is not mocked into a fight; he is confronted for hurting people who fed and helped the crew. He hurls himself at Luffy with the same springing charge that flattened him a day before, and Luffy answers with one direct punch that drops him in the street in front of the town that cheered.',
      'The gold goes back to the ship hull by the shore. Nobody says the word revenge. The lesson from Shanks holds: pride is not worth a fight, but a friend’s injury is, and the difference is the only measure Luffy uses.'
    ]),
    beat('world-powers', 'The world moves while the crew looks up', '233–234', [
      'Far from Jaya, Whitebeard receives a letter from Shanks delivered by Rockstar and refuses to read a summons from a man he still thinks of as a boy. On his deck the nurses scold him about his drinking and Ace is already gone, hunting the crewmate who killed a brother and fled. The two greatest pirate crews on the sea have begun circling each other over a single defector.',
      'At Mary Geoise the Government fills Crocodile’s empty chair. A pale man named Laffitte enters the Warlord meeting uninvited and proposes a captain nobody has heard of: Marshall D. Teach. The Marines note Luffy’s new bounty with concern, and in Mock Town Bellamy wakes to learn that the man who felled him with one punch is worth a hundred million.'
    ], 'interlude'),
    beat('take-the-current', 'The Merry rides the water into the sky', '235–236', [
      'Dawn shows the Merry rebuilt into something Cricket’s monkeys are proud of and the crew barely recognises, a stiff-feathered hull with a chicken’s crest. Cricket gives them a heading and a warning, then stands on the shore with his family as the ship sails for a patch of sea where the water has begun to spin. The whirlpool is the door; the eruption beneath it is the stair.',
      'Blackbeard arrives too late. He has come to take Luffy’s head to the Government to buy a Warlord seat, and instead he watches the Knock Up Stream burst upward with a small ship riding its crest. The South Bird points, Nami reads the water, the Merry stays upright, and Jaya drops away below. Cricket, listening to the roar, tells his ancestor that the Straw Hats are on their way to find out.'
    ])
  ],
  battles: [
    battle('bellamy', 'Luffy versus Bellamy', '232', 'Recover Cricket’s stolen gold and answer an attack on the people who helped the crew.', 'Bellamy relies on his spring-loaded legs and the certainty that Luffy will not fight back. Luffy waits, lets the crowd see the charge, then meets it with a single direct strike.', 'Bellamy falls in the street he ruled. The crew returns to the harder task of reaching the sky.', ['Cricket’s gold in a hyena’s hands', 'Luffy walks back into Mock Town', 'Springs coil against the walls', 'One fist, one street, one silence', 'The gold goes home'])
  ],
  legacy: ['Noland’s story will become a history of displacement rather than a moral about foolish belief.', 'Blackbeard’s introduction complicates the language of dreams: sharing an ambition’s intensity does not mean sharing an ethic.']
}),
arc({
  id: 'skypiea', name: 'Skypiea', sagaId: 'sky-island', chapters: [237, 302],
  premise: 'A stolen island in the sky holds a four-hundred-year argument and a bell waiting to answer it.',
  locationIds: ['white-sea', 'angel-island', 'upper-yard', 'shandora', 'giant-jack', 'going-merry'], characterIds: ['luffy', 'zoro', 'nami', 'usopp', 'sanji', 'chopper', 'robin'],
  overview: ['The White Sea is real, and arrival changes wonder into a dispute about ownership. Upper Yard is made of earth carried into the sky with part of Jaya, making it precious to sky-dwellers and sacred to the Shandians who were displaced from it. Enel rules above both populations, using lightning and Mantra to turn surveillance into the appearance of divinity.', 'The Straw Hats enter as confused outsiders, but their treasure hunt intersects with the search for Shandora and the long consequences of Noland’s visit. The central object is a golden bell: wealth to a thief, a historical marker to Robin, a religious inheritance to the Shandians, and the evidence Cricket needs far below. Its sound can carry a truth farther than a battle’s winner can travel.'],
  beats: [
    beat('heavens-gate', 'Visitors become criminals', '237–243', [
      'The Merry lands in a sea of cloud that holds a ship’s weight, and the first creature to greet the crew is a sky fish large enough to swallow the deck. An old knight on a winged horse drives it off, hands them a whistle, and leaves without explaining who he is. At Heaven’s Gate a bored gatekeeper asks a toll the crew cannot pay and waves them through anyway, and a giant shrimp tows the ship up a river of cloud to Angel Island.',
      'Angel Beach is a holiday. Conis and her father Pagaya feed the crew, show them dials that store wind and sound and flame, and lend Nami a waver she learns to ride within the hour. The peace lasts until the White Berets arrive to book them for illegal entry, and Luffy’s reaction to being fined raises the whole crew to the highest criminal class on the island.',
      'The punishment is Upper Yard. While Luffy, Sanji, and Usopp are ashore, the shrimp returns and carries the Merry, with Zoro, Nami, Robin, and Chopper aboard, up the Milky Road to the altar in the forbidden forest. The three left behind can only follow through the trials Enel’s priests have laid across the only routes in.'
    ]),
    beat('ordeal-of-balls', 'Trials in the forbidden forest', '244–250', [
      'Luffy, Sanji, and Usopp take a small boat up the cloud river into the Ordeal of Balls, where the priest Satori fills the air with floating spheres that hide fire, iron, or a dragon made of cloud. He reads their moves before they make them. They win by refusing to give him a clean read: Sanji and Luffy tangle him in his own trap and finish him in mid-air. Only later do they learn that his sight is Mantra, and that every priest has it.',
      'At the altar, Zoro, Nami, and Robin walk into the trees and Robin recognises what the forest is growing over: stonework, carved and old, that does not belong in the sky. Chopper stays with the ship and meets the priest Shura, whose heat lance sets the Merry’s deck burning. He blows the whistle the knight gave them, and Gan Fall arrives on Pierre to fight Shura across the sky and take a spear through the body for it.',
      'On Angel Beach, Conis confesses to the crowd that she guided the strangers into the forest on orders, and the sky answers her honesty with a pillar of lightning that turns the shoreline to glass. She survives it. The people of Angel Island now know what their god does to anyone who tells the truth.'
    ]),
    beat('vearth-by-firelight', 'A campfire on stolen earth', '251–254', [
      'The crew reunites at the altar and compares what they have found: a wounded knight and his horse, an island where soil is sacred because it is scarce, and ruins under the roots. Robin fits the pieces together. Upper Yard is Jaya’s missing half, lifted into the clouds by the same stream that carried the Merry, and the gold Noland described should be lying somewhere in the forest above their heads.',
      'Gan Fall, treated by Chopper, tells them how he lost his throne. He was God of Skypiea before Enel arrived with lightning and a private army, and he has spent the years since as a mercenary knight answering distress whistles. The Shandians, watching from the cliffs, hear none of this. Wyper knows only that outsiders are camping on the land his people have fought four centuries to reclaim.',
      'That night the crew lights a fire on the Merry’s deck and sings, badly and loudly, about treasure. The girl Aisa hears their voices carry, and the Shandian warriors prepare their assault for the dawn. In his shrine, Enel announces a game: eighty-one people are on the island, and by his prediction, in three hours, five will remain.'
    ]),
    beat('survival-game', 'The island becomes a contest', '255–270', [
      'Morning scatters everyone. Luffy, Zoro, Robin, and Chopper split into the forest hunting gold and each other; Nami and the wounded Gan Fall take to the air on Pierre with Aisa in tow; the Shandians ride in on their skates and the priests Ohm and Gedatsu move to meet them. Zoro cuts down the gunman Braham, Luffy trades blows with Wyper before a giant python swallows them both, and Robin puts down the divine commander Yama among the ruins she is trying to read.',
      'Chopper carries the arc’s bravest fight. Left alone against Gedatsu, a priest so absent-minded he suffocates himself in his own swamp cloud, he wins with a rumble ball and his own quick thinking, and then walks into Ohm and is beaten flat. Enel appears only to kill: the Shandian Kamakiri strikes at him and is burned where he stands, an execution the god calls a judgment.',
      'Wyper’s war is not a rebellion. Every Shandian death here is the latest instalment of a struggle that began when their city was torn from the ground, and the Straw Hats are simply in his way. Enel counts the fallen from his throne, correcting his forecast as the hours pass, pleased that the numbers are moving toward five.'
    ]),
    beat('the-city-of-gold', 'Shandora under the roots', '271–278', [
      'Zoro fights Ohm on the roof of the ruins, three swords against an iron whip that changes shape mid-swing, and cuts through the priest and his mount together. The ground gives way beneath the survivors and they fall into Shandora itself: streets, temples, and a Poneglyph standing where the bell tower should be. Robin reads it and learns that the great bell was hoisted above the city long ago, and is not where the Shandians believe.',
      'Enel arrives on foot. He has kept his forecast, and the people in the ruined plaza are his five: Zoro, Robin, Nami, Gan Fall, and Wyper. Wyper presses a Reject Dial to the god’s chest and fires everything he has into it, and for a moment Enel’s heart stops. Then it restarts, because lightning is what a heart runs on, and he drops Zoro, Gan Fall, and Robin one after another.',
      'Nami is the only one he spares, because a woman on a waver looks useful on a long voyage. He shows her the Ark Maxim and the plan behind it: leave Skypiea for the moon and erase the sky islands below on the way out. She agrees to nothing and escapes at the first chance. Down on Angel Island, Conis takes a Den Den Mushi and tells her people to run.'
    ]),
    beat('death-piea', 'Rubber against the lightning god', '279–285', [
      'Luffy climbs out of the python at last and meets Enel in the plaza. The lightning that has ended every fight on this island passes through him and does nothing. Enel, who has never met a body his power ignores, loses his composure for the first time and falls back on his staff, on speed, and finally on a trick: he melts the gold of Shandora around Luffy’s arm and throws him off the edge of the island with a ball he cannot remove.',
      'Maxim rises on a column of cloud and Enel begins Deathpiea, seeding the sky with thunderheads that will pull Angel Island to pieces. Nami fetches Luffy from the clouds on her waver with the gold still on his fist, and Sanji and Usopp climb into the ark to sabotage it from inside. Angel Island is struck, and Conis and Gan Fall’s old subjects watch their home burn from the ground.',
      'Wyper and Zoro, barely standing, understand what has to happen. Giant Jack, the beanstalk that reaches the sky above the ark, is the only road up. Nami drives the waver onto it and Luffy hangs on, and the two men below begin cutting the trunk so that it will fall toward Enel’s ship.'
    ]),
    beat('noland-and-kalgara', 'A friendship broken by geography', '286–292', [
      'Four hundred years before, the explorer Mont Blanc Noland came ashore on Jaya and found the Shandian city dying of a plague its people were fighting with sacrifices. He cut down their sacred trees for medicine, saved them, and was very nearly executed for the insult. Kalgara, the warrior who tried to kill him, became the friend he would cross the world to see again.',
      'Noland sailed home promising to return, and Kalgara promised to ring the great bell so that Noland would hear the city before he saw it. The Knock Up Stream struck first. Half of Jaya rose into the clouds with Shandora and its people on it, and when Noland returned with his king he found sea where the city had stood. He was hanged as a liar, and Kalgara rang the bell into the clouds for a friend who never came.',
      'Wyper is Kalgara’s descendant; Cricket is Noland’s. Neither knows that the other has spent his life trying to keep the promise, and the bell that would tell them both the truth still hangs in the sky.'
    ], 'flashback'),
    beat('ring-the-bell', 'A message to the sea below', '293–302', [
      'Enel builds a thundercloud the size of a town and drops it toward Angel Island. Luffy drives the gold ball on his fist through it and the storm disperses across the sky. Zoro and Wyper bring Giant Jack down against the ark, Nami rides the falling trunk to the top, and Luffy comes up out of the cloud with his arm wound back and the bell tower in sight behind Enel’s head.',
      'The blow goes through the god and into the bell. Its sound rolls down through the cloud layers to the sea, and on Jaya, Cricket hears the city of gold ring for the first time in four centuries. Enel retreats to Maxim and sails for the moon. At the foot of the tower, Robin finds the Poneglyph the bell was guarding, and cut into its base, Gol D. Roger’s words that he came here and read it.',
      'Skypiea and Shandia meet on the burned ground without a god between them. The Straw Hats are honoured with a feast and then, on principle, steal as much gold as the Merry can carry before the hosts can miss it, only to find their hosts are trying to give them a pillar of it. They leave the sky by octopus balloon, with a ship that has been through more than anyone has yet admitted.'
    ])
  ],
  battles: [
    battle('gedatsu', 'Chopper versus Gedatsu', '262', 'Survive alone against a priest while the rest of the crew is scattered.', 'Gedatsu’s swamp clouds swallow anything they touch, but his attention wanders even in a fight. Chopper uses a rumble ball to change shape and tempo faster than the priest can track.', 'Gedatsu falls into his own swamp and out of the sky. Chopper has won a fight with no one watching.', ['A priest who forgets to breathe', 'Rumble ball between the teeth', 'Horn Point tears the ground', 'Gedatsu sinks into his own cloud', 'A reindeer stands alone in the forest']),
    battle('ohm', 'Zoro versus Ohm', '271–272', 'Cut a path through the last priest before Enel’s forecast comes true.', 'Ohm’s iron cloud whip becomes a sword, a net, or a spear between one swing and the next, and his dog Holy weighs a ton. Zoro fights on collapsing ruins with Chopper and Gan Fall already down behind him.', 'A single rising cut finishes the priest and his mount. The floor fails and drops everyone into Shandora.', ['An iron whip changes shape mid-swing', 'Three swords on a crumbling roof', 'The dog charges', 'One rising cut through cloud and iron', 'The ruins open beneath them']),
    battle('wyper', 'Wyper versus Enel', '274–275', 'Kill the god who occupies the Shandian homeland before he can leave it in ruins.', 'Wyper has kept a Reject Dial against Enel for years, knowing that firing it may kill him too. He gets close enough to press it to the god’s chest and empties it.', 'Enel’s heart stops and then restarts on his own lightning. Wyper is burned down, but he has shown the god can bleed.', ['A warrior walks toward the lightning', 'The Reject Dial pressed to a god’s heart', 'Everything fired at once', 'Enel falls silent', 'A heartbeat restarted by thunder']),
    battle('enel', 'Luffy versus Enel', '279–280; 297–299', 'Prevent the destruction of Skypiea and ring the bell for the people still waiting below.', 'Rubber negates Enel’s lightning, but his Mantra, his staff, and a golden ball fused to Luffy’s arm keep the fight dangerous. Luffy must solve the problem of altitude as well as land a decisive blow.', 'The golden fist carries Enel through the bell. Its sound reaches Jaya, and the god leaves for the moon.', ['Lightning passes through rubber', 'A god’s face changes', 'Gold melted around a fist', 'Giant Jack falls toward the ark', 'The bell rings across the clouds'])
  ],
  legacy: ['The ruins establish the Poneglyphs as a connected historical trail, and Roger’s inscription places the former Pirate King on that same path.', 'The liberation settles an immediate tyranny without pretending four centuries of dispossession can be repaired by one punch. The bell allows recognition to begin.']
}),
arc({
  id: 'long-ring-long-land', name: 'Long Ring Long Land', sagaId: 'water-seven', chapters: [303, 321],
  premise: 'A ridiculous pirate game reveals how frightening it would be to lose a crewmate.',
  locationIds: ['long-ring-long-land', 'going-merry'], characterIds: ['luffy', 'zoro', 'nami', 'usopp', 'sanji', 'chopper', 'robin'],
  overview: ['The crew meets Tonjit on an island whose stretched animals and unusual tidal geography invite a lighter adventure. Foxy then challenges Luffy to a Davy Back Fight, a pirate competition in which the stakes are members of the losing crew. Its comedy depends on cheating, bad officiating, and Luffy accepting rules before considering the consequences.', 'Under the jokes is a rehearsal for the losses that follow. Chopper can be removed by a game, Zoro and Sanji must cooperate despite their quarrels, and the captain has to repair a danger he accepted on everyone’s behalf. The arrival of Admiral Aokiji then strips away the comic framework and asks a more serious version of the same question: can Luffy actually keep this crew together against the world’s strongest powers?'],
  beats: [
    beat('tonjit-and-shelly', 'A man on stilts and a horse who waited', '303–304', [
      'Back at sea level, the Merry reaches a flat green island where everything grows long: the grass, the dogs, the foxes, and a set of stilts with an old man on top. Tonjit climbed them ten years ago to please a grandchild and has been unable to get down since. Luffy cuts him free, and the two sit in the grass and eat while the old man explains that his island is one of ten that connect only when the tide falls.',
      'His horse Shelly has waited the whole decade beside the stilts. The reunion lasts until a fleet flying a split-nosed skull anchors offshore and a pistol shot drops the horse in the grass. Foxy the Silver Fox and his crew have come to play, and shooting an old man’s horse is how they announce the rules.'
    ]),
    beat('the-wager', 'People become the prize', '305–307', [
      'Foxy proposes a Davy Back Fight and Luffy, who understands none of it, accepts. The rules are old and binding: three games, and each win lets the victor take a member of the losing crew or its flag. The Foxy Pirates number five hundred because Foxy has been collecting people this way for years, and every one of them was once someone’s nakama.',
      'The first game is the Donut Race, a course around the island in boats built on the spot. Nami, Usopp, and Robin build a fast one and are winning it when Foxy leans over the rail and uses his Slow-Slow Beam, a power that holds anything it touches motionless for thirty seconds. Porche’s boat glides past a frozen crew, and the Foxy Pirates choose Chopper.',
      'Chopper does not go quietly, and Zoro tells him to stop crying because a man made his choice when he joined a pirate crew. It is the harshest thing anyone has said to him, and it is the only comfort available: the crew intends to win him back, and they need him to believe it.'
    ]),
    beat('groggy-ring', 'Rivals share a task', '308–312', [
      'The second game is a ball game in which the ball is a person. Zoro and Sanji, who have not agreed on anything since the Baratie, must carry a crewmate through the Groggy Monsters: Hamburg, Pickles, and the giant fish-man Big Pan, all wearing armour and weapons the referee declines to see. Chopper cheers for the Straw Hats from the Foxy side in a uniform he hates.',
      'The two spend most of the match fighting each other, and it is exactly this that wins it. Their kick and cut land together in the last seconds, driving Big Pan into the goal with the other two monsters riding him. Chopper is chosen back at once, and Luffy learns that the third game is single combat against Foxy himself.'
    ]),
    beat('combat', 'A captain fights on a rigged deck', '313–318', [
      'The final round is fought on the deck of the Sexy Foxy, a ship that Foxy has spent years turning into a fairground of traps. Luffy is slowed thirty seconds at a time, hit with everything the crew can carry, and dropped through the floor. Foxy’s Slow-Slow Beam is not powerful, but it changes the tempo of every exchange and he has practised it against people who fought back.',
      'Luffy improvises rather than adapts. He finds a mirror shard among the wreckage, deflects the beam back at its owner, and lands thirty seconds of punches on a man who cannot move. Foxy falls, and Luffy claims the flag rather than a crew member. The five hundred Foxy Pirates mourn while their new captain, Luffy, paints them a replacement skull so ugly that they beg him to leave.'
    ]),
    beat('captain-and-admiral', 'A game ends; a warning remains', '319–321', [
      'A tall man in a sleep mask is napping on the beach when the crew returns to Tonjit. He is Aokiji, an Admiral of the Marines, and he has come, he says, out of curiosity about the new hundred-million bounty and the woman who joined it. He freezes the sea so that Tonjit can ride to the next island, and then turns to Robin and tells her that every organisation she has ever joined has been destroyed.',
      'Robin attacks first and is frozen where she stands. Luffy fights him alone, by agreement, and Aokiji turns his arm to ice, freezes him solid, and leaves both of them alive because he owed a favour to Saul and because a warning is more useful than a corpse. The crew thaws Robin in the bath and lets Luffy sleep it off.',
      'No one on the Merry says what the day has meant. A stranger has told Robin she brings disaster, and the captain has lost a fight without landing a blow. Both facts board the ship with them and sail toward the shipwrights’ city.'
    ])
  ],
  battles: [
    battle('groggy-ring-match', 'Zoro and Sanji versus the Groggy Monsters', '308–312', 'Win Chopper back from a team allowed to cheat in every way the referee can ignore.', 'Hamburg, Pickles, and Big Pan wear hidden weapons and the referee looks away; the ball is a person and the goal is a fall. Zoro and Sanji argue through the whole match and only cooperate in the last seconds.', 'A simultaneous kick and cut drive all three monsters into the goal. Chopper is chosen back.', ['A crewmate carried as the ball', 'Armour under the jerseys', 'Two rivals refuse to pass', 'Kick and blade land at once', 'Big Pan falls through the ring']),
    battle('foxy', 'Luffy versus Foxy', '313–318', 'Win the final round and protect the crew’s membership.', 'Foxy’s Slow-Slow Beam and prepared arena repeatedly interrupt Luffy’s attacks. Luffy improvises around the tricks rather than mastering a new power.', 'Luffy wins the Davy Back Fight and takes the flag. The crew is whole again, briefly.', ['A rigged ring', 'Thirty frozen seconds', 'The beam turned by a mirror', 'Punches land before time restarts', 'A captain wins back his crew']),
    battle('aokiji', 'Luffy versus Aokiji', '320–321', 'Keep an Admiral away from Robin after he has frozen her where she stood.', 'Luffy insists on fighting alone, and Aokiji does not need to move much. Ice climbs Luffy’s arm, then his body, and the Admiral lets the frozen captain fall on the grass.', 'Aokiji leaves both of them alive as a courtesy and a warning. Luffy has not landed a punch.', ['A lazy man on the beach', 'Robin turned to ice', 'Ice climbs a rubber arm', 'The Admiral walks away', 'A frozen captain in the grass'])
  ],
  legacy: ['The possibility of involuntary separation becomes a real anxiety before Robin’s disappearance and the Merry dispute.', 'Aokiji establishes that Robin carries a danger connected to the Government itself, and that Luffy’s current strength has a clear ceiling.']
}),
arc({
  id: 'water-seven', name: 'Water Seven', sagaId: 'water-seven', chapters: [322, 374],
  premise: 'A broken ship becomes a disagreement about who the crew can afford to lose.',
  locationIds: ['water-seven', 'galley-la-headquarters', 'sea-train', 'going-merry'], characterIds: ['luffy', 'zoro', 'nami', 'usopp', 'sanji', 'chopper', 'robin', 'franky'],
  overview: ['Water Seven seems built to solve the crew’s problems: a city of shipwrights where Skypiea’s gold can purchase repairs and perhaps a new specialist. Instead, the inspection reveals damage the Merry cannot recover from. For Luffy, accepting the diagnosis is a captain’s responsibility. For Usopp, already ashamed after being beaten and robbed, abandoning the ship sounds like a rule under which damaged crewmates might eventually be discarded too.', 'Robin’s disappearance turns that internal fracture into an external crisis. An attack on Mayor Iceburg implicates the Straw Hats, while the city’s trusted workers conceal a Government intelligence operation. The incoming Aqua Laguna creates a deadline independent of anyone’s motives. Emotional decisions, political violence, and geography all converge on the last train leaving the city.'],
  beats: [
    beat('the-merry-cannot-sail', 'The cost of an honest diagnosis', '322–331', [
      'A frog swimming the sea-train tracks and a grandmother named Kokoro at Shift Station point the crew toward Water Seven, a city built in tiers on a rising sea where the streets are canals and the shipyard is the state. Galley-La’s foremen agree to look at the Merry, and a shipwright named Kaku runs the length of the hull and comes back with a verdict: the keel is broken, and a ship with a broken keel cannot be repaired, only replaced.',
      'The same afternoon, Usopp is robbed of most of Skypiea’s gold by the Franky Family and beaten into the pavement when he goes to the Franky House to demand it back. Luffy, Zoro, Sanji, and Chopper flatten the house in reply, but the money is spent and Usopp’s ribs do not heal with the building. He returns to the inn to hear his captain say that the crew will buy a new ship.',
      'The fight that follows is not about wood. Usopp hears that a damaged thing which can no longer keep up will be left behind, and he is the one who was just beaten and robbed. He tells Luffy he is leaving the crew and challenges him for the Merry. Luffy, who has never lost a crewmate, accepts because he does not know how else to answer.'
    ]),
    beat('luffy-and-usopp', 'A duel between friends', '332–333', [
      'They fight on the shipyard at night with the Merry between them. Usopp has prepared everything: smoke, oil, flame, an Impact Dial charged with his own body, and a precise knowledge of where his captain will be standing. He hits Luffy harder than most enemies have, and Luffy, who cannot bring himself to dodge, takes it.',
      'It ends the only way it could. Luffy lands one blow and stands over a friend who cannot rise and will not stop talking. He leaves the ship to Usopp and walks away with the rest of the crew, and the Merry stays where it lies with the sniper who chose it over them.'
    ]),
    beat('the-mayor-is-shot', 'The city turns on its guests', '334–341', [
      'Morning brings a headline: Mayor Iceburg has been shot in the night, and the assassins wore masks and travelled with a tall woman who could grow arms out of a wall. Chopper and Sanji saw Robin walking with a masked man hours earlier and were told to forget her. The Galley-La shipwrights, who worship Iceburg, come for the Straw Hats with tools in hand, and the city closes its canals to them.',
      'Franky returns from a trip to find his house in splinters and hunts down the man responsible. He and Luffy fight through the streets until Franky’s Coup de Vent sends the captain flying and the pursuit scatters both of them. Meanwhile the sky turns yellow. Aqua Laguna, the yearly tide that swallows the lower city, is coming in a day.',
      'Robin meets Sanji and Chopper in an alley long enough to say goodbye. She tells them they will never see her again and gives no reason. The crew that arrived to buy a ship has now lost its sniper, its ship, and its archaeologist, and is wanted for attempted murder.'
    ]),
    beat('cp9-unmasked', 'The city’s familiar faces change', '342–347', [
      'Luffy, Zoro, Nami, and Chopper break into Galley-La headquarters that night to find Robin and clear their names. Robin is there, and so is Paulie, and so are the masked assassins, who remove their masks one by one: Rob Lucci, who has never spoken above a pigeon’s ventriloquism; Kaku, who checked the Merry’s keel; Kalifa, Iceburg’s secretary; and Blueno, the barman. They are CP9, Government agents who have lived in the city for five years to find the blueprints of an ancient weapon.',
      'Iceburg, wounded but awake, tells them the rest. The blueprints for Pluton are not with him; he passed them to Franky years ago. Robin is helping the agents because of a bargain: if she surrenders herself, the Government will not turn the Buster Call that erased Ohara on the Straw Hats. She tells Luffy to leave and never look for her.',
      'Lucci settles the argument. He throws the Straw Hats through the walls of the mansion with a strength none of them has faced since Aokiji, and Robin walks out with the agents while the building burns behind her. Luffy lands wedged between two buildings, unable to move, with the tide coming.'
    ]),
    beat('warehouse-under-the-bridge', 'Franky’s secret in the water', '348–352', [
      'Franky retreats to the Franky Family hideout beneath the bridge, where his followers have been hiding Usopp, and where Franky keeps a stack of drawings he has never let anyone see. CP9 finds him there. He fights Lucci and Kaku with everything his cyborg body holds, and loses. The agents take Franky and Usopp both, for the blueprints in his head and the Merry’s sniper who happened to be present.',
      'Nami finds Iceburg long enough to learn the whole of Robin’s reason, then runs through a city that is evacuating upward. Aqua Laguna is higher than anyone alive has seen, and the lower districts are already under it. Chopper and Nami find Luffy jammed between two walls and Zoro stuck in a chimney, and neither can be pulled free by hand.',
      'Sanji, meanwhile, has gone to the sea train. He watches Robin, Franky, and Usopp loaded aboard the Puffing Tom and steps onto it as it pulls out of Blue Station, alone.'
    ]),
    beat('toms-workers', 'The shipwright who built for the wrong king', '353–357', [
      'Tom was a fish-man shipwright who built the Oro Jackson, the ship that carried Gol D. Roger to the end of the sea. For that he was condemned to death, and for that he asked the court for time: let him build a sea train that would save the sinking city, and judge him afterward. Iceburg and a scrap-loving boy named Cutty Flam were his apprentices, and the Puffing Tom rose out of Water Seven over ten years.',
      'Cutty Flam built warships from junk in his spare time, and a Government agent named Spandam stole them to attack a judicial ship so that the blame would fall on Tom. Tom confessed to a crime he had not committed in order to protect the boys, and was taken away to Enies Lobby. Cutty Flam tried to stop the train that carried him and was crushed beneath it.',
      'He rebuilt himself from wreckage on a scrap island, became Franky, and came home four years later to find Iceburg mayor and himself officially dead. Iceburg gave him one task: keep the Pluton blueprints that Tom had entrusted to them out of every hand that would use them, including the Government’s.'
    ], 'flashback'),
    beat('chase-the-sea-train', 'The rescue begins before the island ends', '358–366', [
      'Nami reaches Luffy with the truth: Robin is not a traitor but a hostage who sold herself for them. Luffy tears himself out of the wall with the news. The crew that remains gathers at Shift Station where Kokoro unveils Rocketman, a prototype train with no brakes, and Paulie and the Galley-La foremen and the Franky Family climb aboard for reasons of their own.',
      'Rocketman leaves the rails behind and rides the flood into the storm. Aqua Laguna rises across the track as a single wall of water; Zoro cuts a train-sized hole in it, and Rocketman goes through. Behind them, Water Seven disappears under the tide it has always survived. The crew that could not agree on a ship has a single direction again.'
    ]),
    beat('the-train-battle', 'Cars uncoupled in the storm', '367–374', [
      'On the Puffing Tom, Sanji works forward through the cars alone, cutting them loose one by one and fighting Wanze, the cook who fights with noodles, and a squad of Marines. Franky and Usopp, who has arrived in a mask and a cape as the hero Sogeking, join him. Between the three of them and the storm, they take the car where Robin is being held.',
      'Robin refuses to be rescued. Sanji offers her his hand and she tells him, coldly, that she will not come, that she cannot come, and that they are killing her by trying. Blueno opens a door in the air and takes her through it before anyone can argue. The Puffing Tom pulls away toward the island where the sun never sets, with Robin aboard.',
      'Rocketman catches up with the last cars in the rain. Zoro cuts Captain T-Bone out of the way on the roof, the crew hauls Sanji, Franky, and Sogeking aboard, and everyone left standing agrees on one thing: they are going to Enies Lobby, and there is no way back from it.'
    ])
  ],
  battles: [
    battle('luffy-usopp', 'Luffy versus Usopp', '332–333', 'Decide possession of the Merry after a disagreement that neither friend knows how to repair.', 'Usopp uses traps, an Impact Dial, and knowledge of Luffy’s movements to compensate for the strength gap. Luffy must fight someone whose ingenuity he values and whose pain he helped cause.', 'Luffy wins, but no one experiences the outcome as success. Usopp keeps the Merry and remains apart from the crew.', ['The ship between them', 'Smoke, oil and a struck match', 'An Impact Dial to the chest', 'Familiar weaknesses used', 'A victory nobody celebrates']),
    battle('luffy-franky', 'Luffy versus Franky', '338–339', 'Franky wants payment for his flattened house; Luffy wants a way through a city that has turned on him.', 'Franky fights with a body full of surprises: iron fists, a cannon in his forearm, and a blast of compressed air that levels buildings. Luffy has nowhere to stand and a mayor to find.', 'Franky’s Coup de Vent hurls Luffy through the streets and the pursuit scatters both men. Nothing is settled.', ['A cyborg in a speedo blocks the street', 'Weapons unfold from an arm', 'Coup de Vent levels the alley', 'Luffy flies over the rooftops', 'Aqua Laguna interrupts the grudge']),
    battle('galley-la-night', 'The Straw Hats versus CP9', '345–347', 'Bring Robin back from the mansion before the agents who shot Iceburg leave the city with her.', 'Four Straw Hats face four agents who have finished pretending to be shipwrights. Zoro finds Kaku faster than any carpenter should be, and Lucci ends the fight almost alone.', 'Lucci throws the crew through the mansion walls. Robin leaves with CP9 and Luffy lands wedged between buildings.', ['Masks come off in Iceburg’s room', 'Lucci speaks without the pigeon', 'A carpenter draws two swords', 'Robin walks out with her captors', 'Through the wall and into the tide']),
    battle('puffing-tom', 'Sanji, Franky and Sogeking on the Puffing Tom', '366–372', 'Take back the car that holds Robin before the sea train reaches Enies Lobby.', 'Sanji fights Wanze’s noodle armour alone, then Franky and a masked Sogeking join him car by car. Zoro handles Captain T-Bone on Rocketman’s roof as the two trains meet in the storm.', 'The cars are cut loose and Wanze and T-Bone fall, but Robin refuses rescue and Blueno takes her away.', ['One cook against a train', 'Noodle armour meets a heel', 'A masked hero climbs aboard', 'T-Bone cut down on the roof', 'A door opens in the air and she is gone'])
  ],
  legacy: ['The arc makes leadership costly: protecting the crew sometimes requires a decision that a loved person experiences as rejection.', 'Franky’s history ties shipbuilding to Ancient Weapons, while Robin’s surrender sets up a rescue whose real objective is persuading her that she is allowed to return.']
}),
arc({
  id: 'enies-lobby', name: 'Enies Lobby', sagaId: 'water-seven', chapters: [375, 430],
  premise: 'To bring Robin home, the crew must first convince her that wanting to live is enough.',
  locationIds: ['enies-lobby', 'tower-of-justice', 'bridge-of-hesitation', 'sea-train', 'going-merry'], characterIds: ['luffy', 'zoro', 'nami', 'usopp', 'sanji', 'chopper', 'robin', 'franky'],
  overview: ['Enies Lobby presents Government judgment as a place where daylight never ends and prisoners do not return. The Straw Hats invade it with shipwrights, outlaws, and the momentum of a rescue that has grown beyond the original crew. Getting close enough to Robin is only the first problem. She expects every refuge to end like Ohara and believes surrender is the only way to spare these friends.', 'The arc’s decisive declaration happens before its decisive fight. Luffy has the Government flag burned and asks Robin what she wants. Her answer makes the ensuing battles a response to her choice, rather than an effort to carry a passive captive away. The institution that called her existence a crime is no longer allowed to speak for her.'],
  beats: [
    beat('storm-the-courthouse', 'The rescue refuses the usual route', '375–382', [
      'Enies Lobby stands on a waterfall that never ends under a sun that never sets, ten thousand soldiers deep. Luffy does not wait for the gate. He is over it and gone before Rocketman arrives, and by the time the train crashes through the front wall he has already fought his way past a battalion. Paulie, the Franky Family, and the Galley-La foremen pour out behind it and take the front lines so that the Straw Hats can run.',
      'Two giants guard the second gate, and Sogeking stops the fight by telling them that Dorry and Brogy are alive and still duelling on Little Garden. Oimo and Kashi, who took this post to buy their captains’ freedom a hundred years ago, learn that they were lied to and change sides on the spot. The gate comes down with a giant on each side of it.',
      'Franky tears free of his escort, Sogeking finds him, and the two run for the tower where Robin has been taken. Spandam, the Government agent who ruined Franky’s life, has her in a room at the top and is already enjoying himself. Sogeking asks Robin the only question that matters, and she does not answer.'
    ]),
    beat('gear-second', 'A body pumped like a heart', '383–388', [
      'Luffy reaches the roof of the courthouse and finds Blueno waiting, the barman who can open doors in the air. Blueno is not the strongest of CP9, but he is fast enough to have ended most fights before they began. Luffy plants his feet, breathes, and begins to steam.',
      'He has been working on this since Aokiji froze him. Gear Second pumps his blood through his rubber body like a piston, doubling his speed until Blueno’s doors cannot open ahead of him. It burns years off his life, and he does not care. Blueno is down in minutes, and Luffy stands on the courthouse roof shouting Robin’s name across the gap.'
    ]),
    beat('the-roof-and-the-tower', 'She asks them to let her die', '389–390', [
      'The rest of the crew climbs to the roof beside him: Zoro, Nami, Sanji, Chopper, Sogeking, and Franky, seven figures against ten thousand soldiers below and the Tower of Justice across the chasm. Robin stands on its balcony with Spandam’s hand on her collar. Luffy tells her they have come to take her home, and she tells them to leave.',
      'Then she says the thing she has never said aloud. She wants to die. She has wanted to die since she was eight, because every person and place that has ever sheltered her was burned for it, and she can no longer bear to watch it happen again. Spandam laughs. Sanji stops him laughing with a look, and the crew waits.'
    ]),
    beat('ohara', 'The child who survived the library', '391–397', [
      'Ohara was an island whose entire wealth was a library, the Tree of Knowledge, and whose scholars had quietly begun reading the Poneglyphs the Government forbade. Robin, at eight, could read them too. Her mother Olvia had left her as an infant to search for the truth of the Void Century, and returned only when the Marines were already closing on the island.',
      'A giant named Saul, a Vice Admiral who deserted rather than carry out the order, washed up on the beach and became Robin’s first friend. Then the Buster Call came: ten warships, five Vice Admirals, and an order to leave nothing standing. Saul froze in the flames under Aokiji’s ice, still laughing so that she would remember how. The scholars carried books into the lake until they drowned.',
      'The Government put a bounty on a child. Robin has spent twenty years learning that no one shelters a Devil Child for long, and she believed it right up until seven people stood on a roof across from her and did not move.'
    ], 'flashback'),
    beat('declaration-of-war', 'The flag burns and she answers', '398–400', [
      'Luffy tells Sogeking to shoot the flag. The World Government’s banner on the Tower of Justice takes a firebird star and burns, and every soldier below understands what has just been declared. Luffy shouts to Robin again, not that they will save her, but that she has not yet said what she wants. She screams that she wants to live, and that she wants to go back to the sea with them.',
      'Franky has been holding the Pluton blueprints against his chest through every fight. He unfolds them in front of Spandam, lights them, and lets the only surviving plans for an ancient weapon burn to nothing, keeping his promise to Tom and taking the Government’s reason for all of this out of the world. Spandam screams; Franky, for once, does not pose.',
      'The crew jumps. Seven people leap from the courthouse roof toward the tower across a bottomless chasm while Kokoro and Chimney find a way beneath. Spandam drags Robin toward the Gates of Justice with five keys to her cuffs handed out among five agents. The rescue becomes a hunt for the right key.'
    ]),
    beat('keys-to-freedom', 'Every fight is part of one rescue', '401–410', [
      'Inside the tower the crew separates to find the agents holding keys. Zoro and Sogeking are handcuffed together by one of them and spend a battle running from Jabra as one animal. Franky meets Fukurou, a round man who cannot keep a secret, and fights him on the tower stairs with a body that runs on cola. Fukurou is beaten and his key is the wrong one.',
      'Chopper faces Kumadori, a theatrical agent who cannot be knocked down, and does what he has sworn never to do: he eats a third rumble ball. The thing that stands up is not Chopper. Monster Point flattens Kumadori and then keeps going, through walls and toward friends, until Franky throws it into the sea to stop it. The key it wins is also wrong.',
      'Spandam meanwhile has reached the tunnel beneath the tower with Robin and Lucci, and Sogeking, from the tower window, puts shots across the chasm to slow him. The Gates of Justice are opening, and once a prisoner passes them, she is beyond any rescue the crew can attempt.'
    ]),
    beat('wolves-and-giraffes', 'The last three keys', '411–417', [
      'Nami fights Kalifa alone in a bathhouse, where the agent’s power turns anything she touches slippery and Nami’s own body slides out of her control. She wins with a storm: the Clima-Tact she has been learning to use since Skypiea finally becomes a weapon, and a lightning bolt drops the woman who once served Iceburg tea. Her key is wrong too.',
      'Sanji finds Jabra, the wolf, and fights him without his hands over a floor of broken stone. Jabra tries to talk him into pity with a story about a daughter; Sanji kicks him through it. The Diable Jambe he lights for the finish is a leg that burns, and the kick that ends the fight is the hottest thing he has thrown.',
      'Zoro and Kaku fight to the roof of the tower and back down through it. Kaku has become a giraffe and is embarrassed about it; his swords cut the tower into slices anyway. Zoro answers with something he has never shown, a nine-sword shape that flickers behind him and cannot be explained. Kaku falls, and the key he carried opens Robin’s cuffs.'
    ]),
    beat('the-bridge-of-hesitation', 'A cat, a captain, and a Buster Call', '418–425', [
      'Luffy reaches the tunnel and meets Rob Lucci, who has become a leopard and stopped pretending. They fight across the bridge to the Gates of Justice while Spandam drags Robin ahead of them and Sogeking’s shots and Franky’s pursuit slow him step by step. Franky frees Robin with Kaku’s key, and she breaks Spandam over her own crossed arms before he can give another order.',
      'Spandam has already made his last mistake. Playing with the Golden Den Den Mushi in Robin’s room, he summoned a Buster Call on his own island. Ten warships arrive and begin firing on Enies Lobby, its soldiers, its agents, and everyone the Straw Hats brought with them. Kokoro, revealed as a mermaid, carries the crew through the flooded tunnel to the bridge.',
      'Lucci is stronger than anything Luffy has faced. Gear Third swells his bones and hits the leopard with a fist the size of a house, and Lucci still stands. The crew watches from the far end of the bridge, unable to help, while Marine cannon fire lands closer with every volley.'
    ]),
    beat('the-last-ship', 'A farewell that was also a rescue', '426–430', [
      'Luffy cannot rise. Usopp, still in the mask, shouts at him across the water that a captain who fell here would leave everyone behind, and Luffy gets up on the voice alone. He drives Lucci back with a barrage of punches that does not stop until the leopard falls. The crew has no ship, warships on three sides, and a captain who has to be carried.',
      'A voice calls them from the sea below. The Going Merry, which they left broken on the shipyard, has crossed the ocean by itself to fetch them. They drop into it and it takes them through the cannon fire, the falling debris, and the storm, past Buster Call ships that cannot turn in time, and out into open water where Galley-La and the Franky Family are waiting.',
      'The keel breaks at last. Luffy sets the Merry alight with a torch in falling snow, and the crew hears the ship thank them for carrying it as far as it could go. Nobody can answer that with repairs. They watch it burn until it sinks, and they weep the way they have not allowed themselves to since the shipyard.'
    ])
  ],
  battles: [
    battle('fukurou', 'Franky versus Fukurou', '404–405', 'Beat a CP9 agent on the tower stairs and take the key he carries.', 'Fukurou is round, fast, and cheerfully indiscreet. Franky answers with cola-powered fists and a body built to withstand a train, but the tower is narrow and the agent knows it.', 'Franky wins with a Coup de Vent at point-blank range. The key is not Robin’s.', ['A round man who talks too much', 'Franky refuels on cola', 'Fists on the tower stairs', 'Coup de Vent at point blank', 'The wrong key in a cyborg’s hand']),
    battle('kumadori', 'Chopper versus Kumadori', '406–408', 'Survive an agent who cannot be put down, and find the key he holds.', 'Kumadori controls his own body to the point of refusing to die. Two rumble balls are not enough, and Chopper swallows a third knowing what it may do.', 'Monster Point crushes Kumadori and turns on the tower. Franky throws Chopper into the sea to stop him.', ['An agent who declaims before every blow', 'Two rumble balls fail', 'The third goes down', 'Something huge stands where Chopper was', 'Franky throws his friend into the sea']),
    battle('kalifa', 'Nami versus Kalifa', '411–413', 'Take a key from a CP9 agent whose touch makes the body slip out of anyone’s control.', 'Kalifa’s bubbles leave Nami sliding on her own skin. Nami fights the way she navigates, building a storm inside a bathhouse one temperature at a time.', 'Lightning ends it. Nami has won a fight without anyone stepping in.', ['Bubbles on a bathhouse floor', 'A body slips out of control', 'Hot and cold gather under the ceiling', 'Thunderbolt Tempo', 'The secretary falls']),
    battle('jabra', 'Sanji versus Jabra', '414–415', 'Get past the wolf between the crew and Robin without using his hands.', 'Jabra lies as easily as he fights, and his wolf form is fast and heavy. Sanji lights his leg for the first time and turns the floor into an oven.', 'Diable Jambe puts Jabra through the stone. Another key, and another wrong one.', ['A wolf tells a story about a daughter', 'Sanji does not believe it', 'A leg begins to glow', 'Diable Jambe', 'Flames through the tower floor']),
    battle('kaku', 'Zoro versus Kaku', '416–417', 'Settle the duel with the swordsman who diagnosed the Merry and now guards Robin’s last key.', 'Kaku’s new giraffe form embarrasses him and cuts the tower to pieces anyway. Zoro fights through floors as they collapse and reaches for a shape he has never shown.', 'Asura brings Kaku down. The key he carried is the one that opens Robin’s cuffs.', ['A shipwright draws two swords', 'A giraffe cuts the tower in slices', 'Floors fall away beneath them', 'Nine swords in the smoke', 'The right key at last']),
    battle('lucci', 'Luffy versus Rob Lucci', '418–427', 'Keep Lucci from killing the escaping crew and prove that Robin’s chosen home can survive this rescue.', 'Gear Second and Gear Third allow Luffy to challenge CP9’s strongest fighter, but both carry costs. Lucci’s durability makes the confrontation an endurance test, and Usopp’s call reconnects Luffy’s failing body to the people relying on him.', 'Luffy defeats Lucci with a final barrage and must be carried into the escape.', ['The tunnel to the bridge', 'A leopard stops pretending', 'A giant fist', 'A friend calls from across the gap', 'The final barrage'])
  ],
  legacy: ['Robin’s declaration establishes belonging as a right the crew will defend without requiring her to justify her usefulness.', 'The Merry’s last rescue resolves the ship’s story through care rather than repair. The crew has lost its home while proving the relationships inside it can continue.']
}),
arc({
  id: 'post-enies-lobby', name: 'Post-Enies Lobby', sagaId: 'water-seven', chapters: [431, 441],
  premise: 'A new ship can carry the crew onward only after an old argument is answered.',
  locationIds: ['water-seven', 'thousand-sunny'], characterIds: ['luffy', 'zoro', 'nami', 'usopp', 'sanji', 'chopper', 'robin', 'franky'],
  overview: ['Back in Water Seven, recovery includes more than healing injuries. The crew has openly challenged the World Government, lost the Merry, and left Usopp’s membership unresolved. New bounties make the consequences public, while Garp’s arrival reveals how much of Luffy’s family history his companions have never heard.', 'Franky uses the stolen money’s surviving value—Adam wood—to build a ship suited to the future he wants to see. His dream is not complete when the vessel leaves the yard; he needs to sail with it. The Thousand Sunny therefore arrives as both a replacement home and an invitation to its maker, but the new beginning does not automatically remove the need for an apology from the friend who left.'],
  beats: [
    beat('a-family-of-surprises', 'Garp arrives with Coby', '431–434', [
      'The crew is asleep in Galley-La’s guest house when a Vice Admiral punches through the wall and knocks Luffy across the room with a fist he calls love. Monkey D. Garp is Luffy’s grandfather, the man who threw him into jungles as a child to make a Marine of him, and he has come to see the boy who just burned the Government’s flag. Two young Marines stand behind him at attention: Coby and Helmeppo.',
      'Garp talks more than he should. Luffy’s father is Dragon, the most wanted revolutionary alive, a fact Luffy hears with the same blank face as everyone else. Coby has learned to fight and has learned, from Garp, what the Four Emperors are. Far away, two of those Emperors are meeting: Shanks boards Whitebeard’s ship to ask him to call Ace back from his hunt, and when the old man refuses, their clash splits the sky.'
    ]),
    beat('wanted', 'The price of a burned flag', '435', [
      'The newspaper arrives with the whole crew in it. Luffy is now worth three hundred million, Zoro a hundred and twenty, Robin eighty, Franky forty-four, Nami sixteen, Sogeking thirty, Chopper fifty. Sanji, whose photograph was never taken, is represented by a sketch so bad that he cannot look at it. Chopper is listed as a pet.',
      'Iceburg, the shipwrights, and the Franky Family read the same page and understand what the numbers mean: the people they helped are now the Government’s enemies, and Water Seven cannot keep them. The Franky Family goes to Luffy with a request instead of a demand. Take Franky with you, they say. He has been building the ship you need since you arrived.'
    ]),
    beat('the-dream-ship', 'A shipwright finishes the beginning', '436–437', [
      'Franky has spent the crew’s stolen gold on the only thing worth spending it on: a length of Adam wood, the tree that does not break. With Iceburg and the Galley-La foremen he builds a ship around it in the shipyard while the crew heals, a lion-headed brigantine with a lawn on deck and a soldier dock in its hull, and refuses every invitation to sail on it.',
      'Robin settles the matter by seizing something Franky cannot leave behind and walking toward the shipyard with it. The Franky Family lines up to tell their boss what Tom would have told him: a ship is only finished when it reaches the end of the sea, and its builder ought to be aboard. Franky puts his speedo on, and Iceburg gives the ship its name. The Thousand Sunny is launched with a shipwright who is now a Straw Hat.'
    ]),
    beat('an-apology-and-a-departure', 'The crew makes room without erasing the breach', '438–439', [
      'Usopp waits on the pier for someone to ask him back, and nobody does. Zoro is the one who says why: a man who left the crew and drew a weapon on its captain does not get to stroll back aboard as if nothing happened, and if Luffy lets him, Zoro will leave. It is the coldest and the most loyal thing anyone says in the arc, and Luffy accepts it.',
      'Garp attacks at dawn with a fleet, throwing cannonballs by hand, and the Sunny casts off under fire. Usopp runs down the pier behind it shouting the apology he has rehearsed for a week, and Luffy’s arm stretches back across the harbour to pull him aboard. Franky lights the Coup de Burst for the first time and the Sunny leaves Water Seven through the air.'
    ]),
    beat('banaro-island', 'Fire meets darkness', '440–441', [
      'On Banaro Island, Portgas D. Ace finally catches the man he has hunted since Jaya. Marshall D. Teach was a Whitebeard Pirate until he killed a crewmate for the Dark-Dark Fruit and ran, and he greets his old commander with an offer to join his new crew and a plan to take Luffy’s head to the Government. Ace declines both.',
      'Their fight burns and swallows the town. Ace’s fire meets a darkness that pulls it in and pulls Ace with it, and each time Teach’s hand closes on him his flame goes out. It is the first Devil Fruit that has ever answered another. The chapter ends with two attacks meeting above the ruins, and the crew on the Sunny knows nothing of it.'
    ], 'interlude')
  ],
  battles: [
    battle('garps-fists', 'The Thousand Sunny versus Garp’s fleet', '438–439', 'Leave Water Seven with the whole crew aboard before a Vice Admiral sinks the new ship.', 'Garp hurls cannonballs by hand and means at least some of them. The Sunny has never sailed and Usopp is still on the pier.', 'Luffy hauls Usopp aboard and Franky fires the Coup de Burst. The Sunny escapes through the air.', ['Cannonballs thrown like baseballs', 'Usopp runs the length of the pier', 'An arm stretches back across the harbour', 'Coup de Burst', 'The Sunny leaves Water Seven flying']),
    battle('ace-blackbeard', 'Ace versus Blackbeard', '440–441', 'Ace seeks accountability for Blackbeard’s killing of a fellow Whitebeard pirate.', 'Blackbeard’s darkness can draw an opponent toward him and suppress Devil Fruit powers through contact, forcing Ace to confront a threat unlike an ordinary elemental duel.', 'The closing confrontation leads to Ace’s capture, revealed as the wider war story develops.', ['A town on Banaro Island', 'An offer refused', 'Darkness pulls inward', 'Fire snuffed in a closed hand', 'Two powers collide'])
  ],
  legacy: ['The Sunny and Franky make the repaired crew materially ready for a longer voyage.', 'Usopp’s return keeps forgiveness compatible with accountability. Ace’s defeat, meanwhile, begins a crisis that no ship upgrade can solve.']
}),
arc({
  id: 'thriller-bark', name: 'Thriller Bark', sagaId: 'thriller-bark', chapters: [442, 489],
  premise: 'A ship full of stolen shadows asks whether a promise can survive death.',
  locationIds: ['florian-triangle', 'thriller-bark', 'hogback-mansion', 'thousand-sunny'], characterIds: ['luffy', 'zoro', 'nami', 'usopp', 'sanji', 'chopper', 'robin', 'franky', 'brook'],
  overview: ['The Florian Triangle hides a gigantic ship arranged as a haunted island. Its zombies are not simply resurrected people: Gecko Moria combines corpses with shadows stolen from the living, creating obedient fighters while condemning the original owners to avoid sunlight. The grotesque comedy conceals a system that treats bodies, memories, and identities as parts for someone else’s army.', 'Brook, a skeleton returned by the Revive-Revive Fruit, initially seems the perfect inhabitant of the setting. He is actually its loneliest captive. Recovering his shadow would let him leave, but the reason to leave is older than Moria’s trap: he promised to return to a whale the Straw Hats have already met.'],
  beats: [
    beat('a-gentleman-skeleton', 'A skeleton asks to see Nami’s panties', '442–444', [
      'The Sunny sails into the Florian Triangle, a stretch of permanent fog where ships vanish, and a barrel drifting past turns out to be a flare. Out of the mist comes a wrecked ghost ship with a single passenger: a tall skeleton in a top hat and a torn coat who introduces himself as Brook, plays the violin, and asks a series of questions that end with Luffy inviting him to join the crew.',
      'Over dinner he explains that he ate a Devil Fruit that returned his soul to his body after death, but that his body had rotted to bone before the soul found it. He cannot leave the fog: his shadow was stolen, and sunlight would destroy him. When a gate rises in the dark and pulls the Sunny inside an island, Brook says he knows the place too well, and goes off alone into it.'
    ]),
    beat('hogbacks-mansion', 'The doctor and the maid', '445–450', [
      'Thriller Bark is a ship the size of an island with a mansion, a forest, and a graveyard on its deck. Nami, Usopp, and Chopper are separated from the others and take shelter with Doctor Hogback, a surgeon famous enough that Chopper has read his papers, and his maid Cindry, who serves dinner by smashing plates. The house is full of things that move when no one looks.',
      'Luffy, Zoro, Sanji, Robin, and Franky follow the graveyard and are attacked by the dead, and Luffy decides that a zombie who can be knocked down can be recruited. A vast man in the shadows above them, Gecko Moria, is one of the Seven Warlords and this is his kingdom. Every zombie here carries a shadow he has cut from a living person, and every shadow’s owner is now forbidden the sun.',
      'Usopp works out what the maid is by matching her face to a poster of a dead actress. Hogback’s genius is the manufacture of corpses that serve, and his devotion to Cindry did not end when she died. An invisible man carries Nami out of her bath, and the mansion stops pretending to be a refuge.'
    ]),
    beat('the-stolen-shadows', 'The dead borrow the living', '451–458', [
      'Perona the Ghost Princess keeps a garden of stuffed animals that walk, and her hollow ghosts pass through a person and leave them face-down and apologising for having been born. Brook, back among his enemies, explains the rules to the trapped crew: salt purifies a zombie, and a shadow returns to its owner when the zombie is cleansed. He has been on this island hunting the samurai who carries his own.',
      'Moria’s scissors cut Luffy’s shadow from his feet, and Zoro’s and Sanji’s follow. The captain’s shadow goes into the largest corpse on the island, Oars, a giant the size of a fortress who once fought as a demon in a frozen land. The three shadowless men wake at dawn in the mansion with no reflection, no shadow, and a few hours of night left.',
      'Absalom, the invisible man, has decided to marry Nami whether or not she is awake for it. Oars sits up in his frozen tomb, eats the meal Luffy would have wanted, and goes looking for adventure in a way the crew finds terribly familiar.'
    ]),
    beat('the-scattered-fights', 'Everyone is somebody else’s enemy', '459–469', [
      'Oars walks through the mansion wall and the crew scatters to fight the island one piece at a time. Sanji finds the wedding and drops Absalom in front of the altar before he can kiss the bride. Usopp, whose despair is already so complete that Perona’s ghosts have nothing to add, is the only one who can stand up to her, and does, with a hammer that is mostly balloon.',
      'Brook fights the zombie samurai Ryuma for his shadow and loses, as he has lost every time; his sword arm is not what it was. Zoro takes the duel over and finds a dead swordsman whose technique deserves the legend attached to it. He wins, and Ryuma, before he burns, gives him his sword: Shusui, the black blade of Wano.',
      'Chopper and Robin corner Hogback in his laboratory and Chopper says what the doctor cannot bear to hear: the woman he built is not the woman he loved, and every command he gives her is proof. Cindry’s tears fall and Hogback runs. In the forest, Lola the boar-headed bride and the shadowless survivors of the island crawl out of hiding to offer the Straw Hats an alliance.'
    ]),
    beat('against-oars', 'A crew fights its captain’s shadow', '470–475', [
      'The crew comes together on the courtyard against Oars, and Oars fights like Luffy, stretching limbs he does not have because the shadow believes it can. Nothing individual works. Franky and Robin build a tower of the crew’s bodies, Chopper finds the giant’s weak joints, Nami calls lightning down on his head, and Sanji and Zoro cut and kick the legs from under a mountain. It stands up every time.',
      'Bartholomew Kuma steps out of the dark in a Marine coat and a bear cap and tells Moria that the Government has news: Ace has been captured and Blackbeard has taken Crocodile’s empty seat among the Warlords. He asks Moria a question he has been sent to ask, teleports Perona out of the island with a touch, and goes back into the shadows to watch.',
      'Moria climbs into Oars’s belly and begins moving the giant with his own shadow. The crew, broken and bleeding, is running out of tricks, and Nami runs into the forest looking for the only allies the island has left.'
    ]),
    beat('nightmare-luffy', 'A hundred shadows, one dawn', '476–482', [
      'Lola and the Risky Brothers pour a hundred stolen shadows into Luffy, and what stands up is a dark giant with his face, the strength of a hundred fighters and about ten minutes of time. Nightmare Luffy takes Oars apart, drives Moria out of the giant’s stomach, and hits the Warlord across the courtyard before the shadows spill out of him and he drops.',
      'Oars is still not finished, and the crew finishes him together: Robin and Franky pin the giant, Zoro, Sanji, and Usopp lock his limbs, Nami puts a bolt through his spine, and Luffy comes down with both fists. Moria answers by swallowing every shadow on the island, a thousand of them, and swelling into something that fills the courtyard.',
      'The sky is greying. Luffy, with the sun behind his shoulder, hits Moria until the shadows come out of him like a fountain, and each one finds its way home before the light reaches its owner. Brook stands in the dawn and does not burn. His shadow is under his feet.'
    ]),
    beat('nothing-happened', 'The price after the victory', '483–485', [
      'Kuma has orders: the Government cannot afford a public account of a Warlord’s defeat, and everyone on the island who could give one is to be erased. He offers Luffy’s head as the price of everyone else’s lives. Zoro answers by offering his own instead, and Sanji, who tries to make the same offer, is knocked unconscious by his rival for it.',
      'Kuma accepts on a condition. He draws the pain and fatigue out of Luffy’s body into a sphere that shakes the ground, and tells Zoro that if he wants to trade his life he can take this instead. Zoro asks only that Kuma let him choose the place, and walks into it.',
      'Sanji finds him standing at dawn in a clearing painted red, upright and breathing and unable to speak. When Sanji asks what happened, Zoro tells him that nothing happened, and that is the only account of the night the crew will ever receive from him.'
    ]),
    beat('the-last-song', 'Laboon’s missing answer', '486–489', [
      'Brook was a musician and swordsman in the Rumbar Pirates, a crew that sang everywhere and left a whale calf at the Red Line with a promise to come back for it. In the Grand Line they were poisoned in an ambush, and in their last hours they recorded Bink’s Sake into a Tone Dial, playing on as one by one the players stopped. Brook was the last, and then the silence.',
      'His soul came back for his body a year later and could not find it in the fog, and by the time it did the body was bones. He steered a ship of the dead for fifty years alone, keeping the promise by remembering the song, until Moria took his shadow and even the fog became a cage.',
      'Luffy tells him that Laboon is still waiting at the cape, still singing at the mountain, still bearing the flag he painted. Brook, who had nothing left to hope for, weeps without eyes and accepts the place he was offered on the first night. The Sunny leaves the fog with a musician aboard and a song that has somewhere to go.'
    ], 'flashback')
  ],
  battles: [
    battle('ryuma', 'Zoro versus Ryuma', '466–467', 'Free Brook’s shadow from a dead swordsman whose skill has beaten its owner every time.', 'Ryuma fights with a corpse’s patience and a master’s technique, and each exchange cuts the mansion around them. Zoro treats him as a swordsman worth the respect, not a zombie to be salted.', 'Zoro wins and Ryuma, burning, gives him Shusui. Brook’s shadow returns to him.', ['A legend in a dead man’s body', 'Two swordsmen bow', 'Cuts cross in the ballroom', 'Ryuma burns standing', 'Shusui changes hands']),
    battle('oars-moria', 'The Straw Hats versus Oars', '470–480', 'Bring down a giant carrying the captain’s shadow before dawn destroys the shadows’ owners.', 'Oars fights with Luffy’s instincts and a mountain’s weight, and Moria drives him from inside. Team formations, Nightmare Luffy’s ten minutes, and a final coordinated assault are all needed to stop him.', 'The crew pins Oars and Luffy breaks his spine. Moria crawls out of the wreck with the fight not yet over.', ['A giant with Luffy’s instincts', 'The crew stacks into a tower', 'A dark giant wears Luffy’s face', 'Every hand holds one limb', 'Oars falls across the courtyard']),
    battle('moria', 'Luffy versus Gecko Moria', '481–482', 'Force a thousand stolen shadows out of a Warlord before sunrise reaches the people who own them.', 'Moria swallows every shadow on the island and swells beyond the courtyard. Luffy hits him from the mast, from the air, and from the ground as the sky lightens behind him.', 'The shadows spill out and race home. Brook stands in the sunrise unharmed.', ['A thousand shadows swallowed at once', 'The Warlord fills the courtyard', 'A fist against a rising sun', 'Shadows pour out like a fountain', 'A skeleton stands in the dawn'])
  ],
  legacy: ['Brook joins the first Grand Line promise to the present crew, making Laboon’s wait part of an ongoing relationship rather than a forgotten side story.', 'Zoro’s sacrifice and Kuma’s strange conduct leave a private debt and an unresolved mystery that will reshape the meaning of the crew’s next defeat.']
}),
];
